import 'package:flutter/material.dart'; import '../providers/app_state.dart'; import '../widgets/common.dart';
class MilestonesScreen extends StatelessWidget{final AppState state;const MilestonesScreen({super.key,required this.state});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(24),children:[Text('Milestones',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:18),...state.workspace.milestones.map((m){final tasks=state.workspace.tasks.where((t)=>t.milestoneId==m.id).toList();final done=tasks.where((t)=>t.status.toString().endsWith('done')).length;final p=tasks.isEmpty?0:done/tasks.length;return Padding(padding:const EdgeInsets.only(bottom:12),child:GitCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(m.title,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold))),if(m.dueDate!=null)Text('Due ${m.dueDate!.day}/${m.dueDate!.month}')]),const SizedBox(height:6),Text(m.description),const SizedBox(height:14),LinearProgressIndicator(value:p),const SizedBox(height:6),Text('$done completed · ${tasks.length-done} remaining')])));})]);}
